//! Fixed deployed directory names shared by Rust and generated viewer code.

/// Public read-model, viewer asset, and live capability namespace.
pub const VIEWER_DIRECTORY: &str = "mokly-viewer";
/// Generated document, stylesheet, and asset route namespace.
pub const GENERATED_DIRECTORY: &str = "mokly-generated";

/// Generate the two fixed runtime constants for browser path builders.
pub fn typescript() -> String {
    format!(
        "// Generated by cargo xtask generate-types. Do not edit.\n\nexport const VIEWER_DIRECTORY = \"{VIEWER_DIRECTORY}\" as const;\nexport const GENERATED_DIRECTORY = \"{GENERATED_DIRECTORY}\" as const;\n"
    )
}

/// A route beneath the package-owned viewer namespace.
pub fn viewer(path: &str) -> String {
    format!("{VIEWER_DIRECTORY}/{path}")
}

/// A generated document or resource path relative to the artifact root.
pub fn generated(route: &str) -> String {
    format!("static/{GENERATED_DIRECTORY}/{route}")
}
